sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    c.userInitials = "U";


    /*
     * --------------------------------------------------
     * INITIAL VALUES
     * --------------------------------------------------
     */

    c.showRoleMenu = false;

    c.showProfileMenu = false;

    /*
     * Default value remains Student.
     * Server will automatically replace this with
     * Organizer when the logged-in user is an organizer.
     */

    c.selectedRole = "Student";

    c.studentEmail = "";

    c.reliabilityScore = 0;


    /*
     * --------------------------------------------------
     * LOCAL STORAGE KEYS
     * --------------------------------------------------
     */

    var LAST_OPENED_KEY =
        "campus_connect_notifications_last_opened";

    var DELETED_KEY =
        "campus_connect_notifications_deleted";


    /*
     * --------------------------------------------------
     * GET LAST OPENED
     * --------------------------------------------------
     */

    function getLastOpened() {

        return $window.localStorage.getItem(
            LAST_OPENED_KEY
        ) || "";

    }


    /*
     * --------------------------------------------------
     * GET DELETED NOTIFICATIONS
     * --------------------------------------------------
     */

    function getDeletedIds() {

        try {

            return JSON.parse(
                $window.localStorage.getItem(
                    DELETED_KEY
                ) || "[]"
            );

        } catch (e) {

            return [];

        }

    }


    /*
     * --------------------------------------------------
     * LOAD STUDENT PROFILE
     * --------------------------------------------------
     */

    function loadStudentProfile() {

        c.server.get({

            action: "load_profile",

            lastOpened: getLastOpened(),

            deletedIds: getDeletedIds()

        }).then(
            function(response) {

                var result =
                    response.data;


                /*
                 * Email
                 */

                c.studentEmail =
                    result.student_email ||
                    "";


                /*
                 * Reliability Score
                 */

                c.reliabilityScore =
                    result.reliability_score ||
                    0;


                /*
                 * Notification count
                 */

                c.data.notification_count =
                    result.notification_count ||
                    0;


                /*
                 * Current User Initials
                 */

                c.userInitials =
                    result.user_initials ||
                    "U";


                /*
                 * --------------------------------------------------
                 * AUTOMATIC ROLE
                 * --------------------------------------------------
                 *
                 * Student login  -> Student
                 * Organizer login -> Organizer
                 */

                c.selectedRole =
                    result.user_role ||
                    "Student";

            }
        );

    }


    /*
     * --------------------------------------------------
     * ROLE MENU
     * --------------------------------------------------
     */

    c.toggleRoleMenu = function() {

        c.showRoleMenu =
            !c.showRoleMenu;


        /*
         * Close profile menu
         */

        c.showProfileMenu =
            false;

    };


    c.selectRole = function(role) {

        c.selectedRole =
            role;

        c.showRoleMenu =
            false;

    };


    /*
     * --------------------------------------------------
     * PROFILE MENU
     * --------------------------------------------------
     */

    c.toggleProfileMenu = function() {

        c.showProfileMenu =
            !c.showProfileMenu;


        /*
         * Close role menu
         */

        c.showRoleMenu =
            false;

    };


    /*
     * --------------------------------------------------
     * NOTIFICATIONS
     * --------------------------------------------------
     */

    c.openNotifications = function() {

        /*
         * Save current time
         */

        $window.localStorage.setItem(
            LAST_OPENED_KEY,
            new Date().toISOString()
        );


        /*
         * Clear notification badge
         */

        c.data.notification_count =
            0;


        /*
         * Open notification page
         */

        $window.location.href =
            "?id=campus_notifications";

    };


    /*
     * --------------------------------------------------
     * LOGOUT
     * --------------------------------------------------
     */

    c.logout = function() {

        /*
         * Only navigate to the Campus Connect
         * Landing Page.
         *
         * This does NOT log out from ServiceNow.
         */

        $window.location.href =
            "?id=campus_connect_landing_page";

    };


    /*
     * --------------------------------------------------
     * LOAD DATA
     * --------------------------------------------------
     */

    loadStudentProfile();

};

sp_widget.css:
.cc-header {

    width: 107%;

    min-height: 64px;

    background: #ffffff;

    border-bottom: 1px solid #dbeafe;

    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 0 24px;

    box-sizing: border-box;

    font-family:
        "Segoe UI",
        Arial,
        sans-serif;
  margin-left: 100px;
  margin-right:50px;

}
.cc-logout-icon {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #1976d2;
    display: inline-block;
    margin-right: 8px;
}.cc-logout-btn {
    color: #1976d2;
}

/* -----------------------------------
   SEARCH
----------------------------------- */

.cc-header-search {

    display: flex;

    align-items: center;

    width: 420px;

    height: 40px;

    background: #eff6ff;

    border: 1px solid #bfdbfe;

    border-radius: 8px;

    padding: 0 20px 0 5px;

}


.cc-search-icon {

    font-size: 22px;

    color: #2563eb;

    margin-right: 8px;

}


.cc-header-search input {

    width: 100%;

    border: none;

    outline: none;

    background: transparent;

    color: #1e3a8a;

    font-size: 14px;

}


.cc-header-search input::placeholder {

    color: #64748b;

}


/* -----------------------------------
   RIGHT SIDE
----------------------------------- */

.cc-header-right {

    display: flex;

    align-items: center;

    gap: 16px;

}


/* -----------------------------------
   NOTIFICATION
----------------------------------- */

.cc-notification-btn {

    position: relative;

    width: 42px;

    height: 42px;

    border: none;

    background: transparent;

    color: #1e3a8a;

    border-radius: 8px;

    cursor: pointer;

    font-size: 20px;

}


.cc-notification-btn:hover {

    background: #eff6ff;

}


.cc-notification-count {

    position: absolute;

    top: 1px;

    right: 0;

    min-width: 19px;

    height: 19px;

    padding: 0 5px;

    border-radius: 10px;

    background: #dc2626;

    color: #ffffff;

    font-size: 11px;

    font-weight: 700;

    display: flex;

    align-items: center;

    justify-content: center;

}


/* -----------------------------------
   ROLE SELECTOR
----------------------------------- */

.cc-role-selector {

    position: relative;

}


.cc-role {

    height: 42px;

    padding: 0 12px;

    border: 1px solid #bfdbfe;

    background: #ffffff;

    color: #1e3a8a;

    border-radius: 8px;

    cursor: pointer;

    font-weight: 600;

}


.cc-role:hover {

    background: #eff6ff;

}


.cc-chevron {

    margin-left: 6px;

}


.cc-role-menu {

    position: absolute;

    top: 48px;

    right: 0;

    width: 180px;

    background: #ffffff;

    border: 1px solid #bfdbfe;

    border-radius: 10px;

    box-shadow:
        0 8px 25px rgba(
            30,
            64,
            175,
            0.15
        );

    z-index: 1000;

    overflow: hidden;

}


.cc-role-option {

    display: flex;

    align-items: center;

    gap: 10px;

    padding: 12px 14px;

    color: #1e3a8a;

    text-decoration: none;

}


.cc-role-option:hover {

    background: #eff6ff;

}


.cc-role-icon {

    font-size: 18px;

}


/* -----------------------------------
   PROFILE
----------------------------------- */

.cc-profile {

    position: relative;

}


.cc-profile-btn {

    display: flex;

    align-items: center;

    gap: 8px;

    border: none;

    background: transparent;

    cursor: pointer;

    padding: 4px 6px;

    border-radius: 8px;

}


.cc-profile-btn:hover {

    background: #eff6ff;

}


.cc-avatar {

    width: 40px;

    height: 40px;

    border-radius: 50%;

    background: #2563eb;

    color: #ffffff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-weight: 700;

    font-size: 14px;

}


.cc-profile-name {

    color: #1e3a8a;

    font-weight: 600;

}


.cc-profile-chevron {

    color: #64748b;

    font-size: 16px;

}


/* -----------------------------------
   PROFILE DROPDOWN
----------------------------------- */

.cc-profile-menu {

    position: absolute;

    top: 52px;

    right: 0;

    width: 280px;

    background: #ffffff;

    border: 1px solid #bfdbfe;

    border-radius: 12px;

    box-shadow:
        0 10px 30px rgba(
            30,
            64,
            175,
            0.18
        );

    z-index: 2000;

    overflow: hidden;

}


.cc-profile-title {

    display: flex;

    align-items: center;

    gap: 8px;

    padding: 16px;

    background: #eff6ff;

    color: #1e3a8a;

    font-weight: 700;

    font-size: 16px;

}


.cc-profile-title-icon {

    font-size: 20px;

}


/* -----------------------------------
   PROFILE ITEMS
----------------------------------- */

.cc-profile-item {

    padding: 14px 16px;

    border-bottom: 1px solid #eff6ff;

}


.cc-profile-label {

    color: #64748b;

    font-size: 12px;

    margin-bottom: 5px;

}


.cc-profile-value {

    color: #1e3a8a;

    font-size: 13px;

    font-weight: 600;

    word-break: break-word;

}


/* -----------------------------------
   SCORE
----------------------------------- */

.cc-score {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-width: 42px;

    height: 32px;

    padding: 0 10px;

    background: #dbeafe;

    color: #1d4ed8;

    border-radius: 16px;

    font-weight: 700;

    font-size: 15px;

}


/* -----------------------------------
   DIVIDER
----------------------------------- */

.cc-profile-divider {

    height: 1px;

    background: #dbeafe;

}


/* -----------------------------------
   LOGOUT
----------------------------------- */

.cc-logout-btn {

    width: 100%;

    padding: 13px 16px;

    border: none;

    background: #ffffff;

    color: #dc2626;

    text-align: left;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;

    display: flex;

    align-items: center;

    gap: 10px;

}


.cc-logout-btn:hover {

    background: #fef2f2;

}


/* -----------------------------------
   MOBILE
----------------------------------- */

@media (max-width: 768px) {

    .cc-header {

        padding: 0 12px;

    }


    .cc-header-search {

        width: 220px;

    }


    .cc-profile-name {

        display: none;

    }


    .cc-profile-chevron {

        display: none;

    }

}

sp_widget.script:
(function() {

    data.notification_count = 0;

    data.student_email = "";
    data.reliability_score = 0;
    data.user_initials = "U";


    /*
     * --------------------------------------------------
     * 1. CURRENT LOGGED-IN USER
     * --------------------------------------------------
     */

    var userSysId = gs.getUserID();

    if (!userSysId) {
        return;
    }


    /*
     * --------------------------------------------------
     * 2. DETERMINE CURRENT USER ROLE
     * --------------------------------------------------
     */

    data.user_role = "Student";

    var organizerGR = new GlideRecord(
        "x_snc_campus_con_0_event_organizers"
    );

    organizerGR.addQuery(
        "organizer_name",
        userSysId
    );

    organizerGR.setLimit(1);
    organizerGR.query();

    if (organizerGR.next()) {

        data.user_role = "Organizer";

    }


    /*
     * --------------------------------------------------
     * 3. GET CURRENT USER DETAILS
     * --------------------------------------------------
     */

    var currentUser = new GlideRecord("sys_user");

    if (currentUser.get(userSysId)) {

        var firstName = String(
            currentUser.getValue("first_name") || ""
        ).trim();

        var lastName = String(
            currentUser.getValue("last_name") || ""
        ).trim();

        var initials = "";

        if (firstName) {

            initials +=
                firstName.charAt(0).toUpperCase();

        }

        if (lastName) {

            initials +=
                lastName.charAt(0).toUpperCase();

        }

        if (!initials && firstName) {

            initials =
                firstName.substring(
                    0,
                    2
                ).toUpperCase();

        }

        if (!initials) {

            initials = "U";

        }

        data.user_initials = initials;

    }


    /*
     * --------------------------------------------------
     * 4. FIND STUDENT PROFILE
     * --------------------------------------------------
     */

    var profile = new GlideRecord(
        "x_snc_campus_con_0_student_profile"
    );

    profile.addQuery(
        "student",
        userSysId
    );

    profile.setLimit(1);
    profile.query();

    if (profile.next()) {

        data.student_email =
            profile.getValue(
                "college_email"
            ) || "";

        var score =
            profile.getValue(
                "reliability_score"
            );

        if (
            score !== null &&
            score !== ""
        ) {

            data.reliability_score =
                parseInt(
                    score,
                    10
                );

        } else {

            data.reliability_score = 0;

        }

    }


    /*
     * --------------------------------------------------
     * 5. NOTIFICATION BADGE
     * --------------------------------------------------
     */

    if (!input) {
        return;
    }


    var lastOpened =
        input.lastOpened || "";


    var deletedIds =
        input.deletedIds || [];


    /*
     * Deleted notification lookup
     */

    var deletedMap = {};

    for (
        var d = 0;
        d < deletedIds.length;
        d++
    ) {

        deletedMap[
            String(
                deletedIds[d]
            )
        ] = true;

    }


    /*
     * Convert last opened time
     */

    var lastOpenedDate = null;

    if (lastOpened) {

        try {

            lastOpenedDate =
                new GlideDateTime(
                    lastOpened
                );

        } catch (e) {

            lastOpenedDate = null;

        }

    }


    /*
     * --------------------------------------------------
     * 6. TEAM JOIN REQUESTS
     * --------------------------------------------------
     *
     * Only Team Lead receives the pending request badge.
     */

    var teamRequests =
        new GlideRecord(
            "x_snc_campus_con_0_team_members"
        );

    teamRequests.addQuery(
        "join_status",
        "requested"
    );

    /*
     * Team -> Team Lead -> Current User
     */

    teamRequests.addQuery(
        "team.team_lead",
        userSysId
    );

    if (lastOpenedDate) {

        teamRequests.addQuery(
            "sys_created_on",
            ">",
            lastOpenedDate
        );

    }

    teamRequests.query();

    while (
        teamRequests.next()
    ) {

        var requestId =
            "team_request_" +
            teamRequests.getUniqueValue();

        if (
            !deletedMap[requestId]
        ) {

            data.notification_count++;

        }

    }


    /*
     * --------------------------------------------------
     * 7. TEAM REQUEST RESPONSES
     * --------------------------------------------------
     *
     * Only the student who originally requested
     * to join receives this badge.
     */

    var teamResponses =
        new GlideRecord(
            "x_snc_campus_con_0_team_members"
        );

    teamResponses.addQuery(
        "student",
        userSysId
    );

    teamResponses.addQuery(
        "join_status",
        "IN",
        "accepted,rejected"
    );

    if (lastOpenedDate) {

        teamResponses.addQuery(
            "sys_updated_on",
            ">",
            lastOpenedDate
        );

    }

    teamResponses.query();

    while (
        teamResponses.next()
    ) {

        var responseId =
            "team_response_" +
            teamResponses.getUniqueValue();

        if (
            !deletedMap[responseId]
        ) {

            data.notification_count++;

        }

    }


    /*
     * --------------------------------------------------
     * 8. EVENT REGISTRATION SUCCESS
     * --------------------------------------------------
     *
     * Only the student who registered receives
     * the notification badge.
     */

    var registrations =
        new GlideRecord(
            "x_snc_campus_con_0_registrations"
        );

    registrations.addQuery(
        "student",
        userSysId
    );

    if (lastOpenedDate) {

        registrations.addQuery(
            "sys_created_on",
            ">",
            lastOpenedDate
        );

    }

    registrations.query();

    while (
        registrations.next()
    ) {

        var registrationId =
            "registration_success_" +
            registrations.getUniqueValue();

        if (
            !deletedMap[
                registrationId
            ]
        ) {

            data.notification_count++;

        }

    }


    /*
     * --------------------------------------------------
     * 9. EVENT DEADLINE REMINDERS
     * --------------------------------------------------
     */

    var events =
        new GlideRecord(
            "x_snc_campus_con_0_events"
        );

    events.addQuery(
        "verification_status",
        "verified"
    );

    events.addNotNullQuery(
        "registration_deadline"
    );

    events.query();


    var now =
        new GlideDateTime();


    while (
        events.next()
    ) {

        var deadline =
            new GlideDateTime(
                events.getValue(
                    "registration_deadline"
                )
            );


        if (
            !deadline.after(now)
        ) {

            continue;

        }


        var difference =
            GlideDateTime.subtract(
                now,
                deadline
            );


        var milliseconds =
            Math.abs(
                difference.getNumericValue()
            );


        var days =
            Math.floor(
                milliseconds /
                (
                    1000 *
                    60 *
                    60 *
                    24
                )
            );


        if (days <= 7) {

            /*
             * Use event creation time as the
             * notification timestamp.
             */

            var eventCreated =
                new GlideDateTime(
                    events.getValue(
                        "sys_created_on"
                    )
                );


            if (
                !lastOpenedDate ||
                eventCreated.after(
                    lastOpenedDate
                )
            ) {

                var deadlineId =
                    "deadline_" +
                    events.getUniqueValue();


                if (
                    !deletedMap[
                        deadlineId
                    ]
                ) {

                    data.notification_count++;

                }

            }

        }

    }

})();
